-- Publish the Gemini model catalog without a provider prefix filter.
--
-- AGY exposes Gemini, Claude, and GPT models through the same `models`
-- command. Preserve the current Profile in immutable history, then atomically
-- advance the current row only when the expected revision and digest match.

INSERT INTO worker_profile_history (
  worker_type_id, revision, schema_version, profile_json, digest,
  actor_user_id, published_at, restoration_reason
)
SELECT worker_type_id, revision, schema_version, profile_json, digest,
       updated_by_user_id, updated_at,
       'Publish all models returned by the AGY CLI'
  FROM worker_profiles
 WHERE worker_type_id = 'gemini'
   AND revision = 2
   AND digest = '5fd32343da7061885a8418db63ec7478a89aa2e263b7c9f6193cb0825c44cf36';

